15	class KernelAdd {
16	public:
17	    __aicore__ inline KernelAdd() {}
18	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, uint32_t totalLength, uint32_t tileNum)
19	    {
20	        this->blockLength = totalLength / AscendC::GetBlockNum();
21	        this->tileNum = tileNum;
22	        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;
23	
24	        xGm.SetGlobalBuffer((__gm__ DTYPE_X*)x + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
25	        yGm.SetGlobalBuffer((__gm__ DTYPE_Y*)y + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
26	        zGm.SetGlobalBuffer((__gm__ DTYPE_Z*)z + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
27	        pipe.InitBuffer(inQueueX, BUFFER_NUM, this->tileLength * sizeof(DTYPE_X));
28	        pipe.InitBuffer(inQueueY, BUFFER_NUM, this->tileLength * sizeof(DTYPE_Y));
29	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, this->tileLength * sizeof(DTYPE_Z));
30	    }
31	    __aicore__ inline void Process()
32	    {
33	        int32_t loopCount = this->tileNum * BUFFER_NUM;
34	        for (int32_t i = 0; i < loopCount; i++) {
35	            CopyIn(i);
36	            Compute(i);
37	            CopyOut(i);
38	        }
39	    }
40	
41	private:
42	    __aicore__ inline void CopyIn(int32_t progress)
43	    {
44	        AscendC::LocalTensor<DTYPE_X> xLocal = inQueueX.AllocTensor<DTYPE_X>();
45	        AscendC::LocalTensor<DTYPE_Y> yLocal = inQueueY.AllocTensor<DTYPE_Y>();
46	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], this->tileLength);
47	        AscendC::DataCopy(yLocal, yGm[progress * this->tileLength], this->tileLength);
48	        inQueueX.EnQue(xLocal);
49	        inQueueY.EnQue(yLocal);
50	    }
51	    __aicore__ inline void Compute(int32_t progress)
52	    {
53	        AscendC::LocalTensor<DTYPE_X> xLocal = inQueueX.DeQue<DTYPE_X>();
54	        AscendC::LocalTensor<DTYPE_Y> yLocal = inQueueY.DeQue<DTYPE_Y>();
55	        AscendC::LocalTensor<DTYPE_Z> zLocal = outQueueZ.AllocTensor<DTYPE_Z>();
56	        AscendC::Add(zLocal, xLocal, yLocal, this->tileLength);
57	        outQueueZ.EnQue<DTYPE_Z>(zLocal);
58	        inQueueX.FreeTensor(xLocal);
59	        inQueueY.FreeTensor(yLocal);
60	    }
61	    __aicore__ inline void CopyOut(int32_t progress)
62	    {
63	        AscendC::LocalTensor<DTYPE_Z> zLocal = outQueueZ.DeQue<DTYPE_Z>();
64	        AscendC::DataCopy(zGm[progress * this->tileLength], zLocal, this->tileLength);
65	        outQueueZ.FreeTensor(zLocal);
66	    }
