70	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX, inQueueY;
71	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
72	    AscendC::GlobalTensor<DTYPE_X> xGm;
73	    AscendC::GlobalTensor<DTYPE_Y> yGm;
